cypress_script:
describe('API endpoint documentation list', () => {
  it('should display the API documentation with correct elements', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('h1').contains('Automation Practice for API Testing');
    cy.get('h2').contains('APIs List for practice');
    cy.get('#susbscribe_email').should('be.visible');
    cy.get('#subscribe').should('be.visible');
  });

  it('should not change URL on empty subscribe', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('#subscribe').click();
    cy.url().should('eq', 'https://automationexercise.com/api_list');
    cy.get('#susbscribe_email').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('API endpoint documentation list', () => {
  test('should display the API documentation with correct elements', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await expect(page.locator('h1')).toHaveText('Automation Practice for API Testing');
    await expect(page.locator('h2')).toHaveText('APIs List for practice');
    await expect(page.locator('#susbscribe_email')).toBeVisible();
    await expect(page.locator('#subscribe')).toBeVisible();
  });

  test('should not change URL on empty subscribe', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await page.click('#subscribe');
    await expect(page.url()).toBe('https://automationexercise.com/api_list');
    await expect(page.locator('#susbscribe_email')).toBeVisible();
  });
});
